    // Printable ASCII through, everything else escaped: a dump of what is in the field is more use
    // here than a guess at what it was meant to say.
    std::string quote(std::string_view s) {
        std::string out;
        out.reserve(s.size() + 2);
        out += '"';
        for (unsigned char c : s) {
            switch (c) {
                case '"': out += "\\\""; break;
                case '\\': out += "\\\\"; break;
                case '\n': out += "\\n"; break;
                case '\r': out += "\\r"; break;
                case '\t': out += "\\t"; break;
                default:
                    if (c >= 0x20 && c < 0x7f)
                        out += static_cast<char>(c);
                    else
                        out += fmt::format("\\x{:02x}", c);
            }
        }
        out += '"';
        return out;
    }

